import{_ as r,l as n,o as e,c as l,v as t,p as s,x as o,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"去优化","description":"","frontmatter":{"title":"去优化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/deoptimization.md","filePath":"cs/deoptimization.md","lastUpdated":1789023840000}'),h={name:"cs/deoptimization.md"};function m(A,a,_,u,E,f){const i=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="去优化" tabindex="-1">去优化 <a class="header-anchor" href="#去优化" aria-label="Permalink to &quot;去优化&quot;">​</a></h1><div class="epigraph"><p>投机编译假设类型、别名、类层次；失败时必须把 native 帧翻译回解释器（或低层 JIT）状态，而不能假装没发生过。</p><footer>—— 据 Hölzle, Chambers and Ungar, Debugging Optimized Code with Dynamic Deoptimization, 1992；HotSpot 去优化说明整理</footer></div><p>上一课<a href="/cs/inline-caching">内联缓存</a> 在失配时要退出投机码。缺口是 <strong>deopt</strong>：映射寄存器与 spill 到字节码栈、PC、锁状态。本课钉为什么必须、元数据，类型反馈下一课是投机的来源。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内联+类型假设后，CFG 不再对应源方法。失败：类加载打破 CHA、IC 失配、守卫失败。必须恢复：解释器能继续。缺口是<strong>栈重写与副作用已发生</strong>（不能回滚 IO），只恢复虚拟机状态。</p><p>OSR（on-stack replacement）是反方向：解释器帧换成 compiled 帧。</p><h3 id="去优化不是「反编译」" tabindex="-1">去优化不是「反编译」 <a class="header-anchor" href="#去优化不是「反编译」" aria-label="Permalink to &quot;去优化不是「反编译」&quot;">​</a></h3><p>不是从机器码还原源。是编译器预先留下的映射表：<code>pc → 字节码索引 + 位置列表</code>。与 DWARF 同类，服务 VM 而非 GDB。</p><p><span class="marginnote">Hölzle et al. 1992 PLDI。HotSpot Deoptimization。本课不写全部帧描述符格式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编译时发 deopt 元数据。运行时：save 寄存器、walk 内联帧链、物化对象（逃逸分析撤销）、跳入解释器。延迟去优化：标记代码为非入口，现有帧在安全点再转。</p>',11)),(e(),s(c,null,{default:o(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAIL%5B%22%E5%AE%88%E5%8D%AB%20%2F%20IC%20%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%20MAP%5B%22%E5%B8%A7%E6%8F%8F%E8%BF%B0%E7%AC%A6%22%5D%0A%20%20MAP%20--%3E%20INT%5B%22%E9%87%8D%E5%BB%BA%E8%A7%A3%E9%87%8A%E5%99%A8%E7%8A%B6%E6%80%81%22%5D%0A%20%20INT%20--%3E%20CONT%5B%22%E7%BB%A7%E7%BB%AD%E6%89%A7%E8%A1%8C%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与<a href="/cs/escape-analysis">逃逸分析</a>：栈化对象在 deopt 时要重新堆分配（物化）。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>安全点：GC 与 deopt 只能在约定点停，否则映射不存在。不要在任意机器指令去优化。锁：膨胀、消除的锁要恢复。</p><p>性能：deopt 应稀。频繁则代码太投机，要降级。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写分层编译阈值。后课默认：投机必须可逆到 VM 状态。下一课类型反馈：给投机提供数据。</p><p>也不把 deopt 当异常 unwind 的别名（可共用展开，语义不同）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>去优化：投机 native → 解释器/低层状态。</li><li>靠编译期映射，不是反编译。</li><li>物化、锁、安全点是实现难点。</li><li>出处：Hölzle, Chambers and Ungar, 1992；HotSpot。</li></ul>',9))])}const b=r(h,[["render",m]]);export{T as __pageData,b as default};
